var t=`0375-carbonnade-flamande`;var a=`world-0375`;var i=`BE`;var o=`western-europe`;var s=4;var r=285;var d={en:`Carbonnade Flamande`,ua:`Фламандська карбонада`};var l={en:`A traditional Belgium dish made with beef chuck, red wine vinegar, dijon mustard, bacon. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Бельгія. Основні інгредієнти: яловича лопатка, червоний винний оцет, діжонська гірчиця, бекон. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`beef-chuck`,850,`g`],[`red-wine-vinegar`,60,`ml`],[`dijon-mustard`,30,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`bacon`,130,`g`],[`unsalted-butter`,55,`g`],[`yellow-onion`,330,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 150 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 150 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:150,i:[[`dark-beer`,650,`ml`],[`beef-stock`,300,`ml`],[`brown-sugar`,35,`g`],[`thyme`,3,`sprig`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:t,id:a,country:`BE`,region:o,servings:4,minutes:285,title:d,text:l,steps:u};export{i as country,g as default,a as id,r as minutes,o as region,s as servings,t as slug,u as steps,l as text,d as title};